(function () {
  // Reuse the host page status snapshot when mounted in the SPA. The direct
  // endpoint remains a fallback for standalone integration tests.
  var csrfToken = "";

  function ensureCsrfToken(callback) {
    if (csrfToken) {
      callback();
      return;
    }
    var statusPromise = window.EliteUI && window.EliteUI.getStatusline
      ? window.EliteUI.getStatusline(15000)
      : fetch("cgi-bin/statusline.cgi", { cache: "no-store" }).then(function (r) { return r.json(); });
    statusPromise.then(function (d) {
      if (d && typeof d.csrf_token === "string") csrfToken = d.csrf_token;
      callback();
    }).catch(function () { callback(); });
  }

  // Minimal Map/Set shims (ES5 has no native Map/Set; accessor "get size()"
  // syntax is ES5-legal, only the Map/Set constructors themselves are ES6).
  function createSimpleMap() {
    var keys = [];
    var values = [];
    return {
      get: function (k) {
        var i = keys.indexOf(k);
        return i === -1 ? undefined : values[i];
      },
      set: function (k, v) {
        var i = keys.indexOf(k);
        if (i === -1) { keys.push(k); values.push(v); } else { values[i] = v; }
        return this;
      },
      "delete": function (k) {
        var i = keys.indexOf(k);
        if (i !== -1) { keys.splice(i, 1); values.splice(i, 1); }
      }
    };
  }

  function createSimpleSet() {
    var items = [];
    return {
      add: function (v) { if (items.indexOf(v) === -1) { items.push(v); } return this; },
      "delete": function (v) { var i = items.indexOf(v); if (i !== -1) { items.splice(i, 1); } },
      get size() { return items.length; },
      toArray: function () { return items.slice(); }
    };
  }

  var recordsMap = createSimpleMap();
  var autoPlayEnabled = false;

  var T = function (m) { return window.tc100T ? window.tc100T(m) : m; };

  function byId(id) {
    return document.getElementById(id);
  }

  function safeParseArray(data) {
    try {
      var parsed = JSON.parse(data);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  function setActionsEnabled(enabled) {
    var downloadBtn = byId("dwbtn");
    var removeBtn = byId("rmbtn");
    if (downloadBtn) {
      downloadBtn.disabled = !enabled;
    }
    if (removeBtn) {
      removeBtn.disabled = !enabled;
    }
  }

  function selectedDate() {
    var dateSelect = byId("dateselect");
    return dateSelect ? dateSelect.value : "";
  }

  function selectedRecord() {
    var recordSelect = byId("recordselect");
    return recordSelect ? recordSelect.value : "";
  }

  function buildRecordFile(date, record) {
    // the list gives HH-MM-SS.mp4 (3.0 recorder) or HH-MM-SS.mkv; older lists gave HH-MM-SS without extension
    return date + "_" + record + (/\.(mp4|mkv)$/.test(record) ? "" : ".mkv");
  }

  function buildRecordUrl(date, record) {
    // file names come from the SD card: encode them (spaces, "#", "?" would break the URL)
    return "/DCIM/" + encodeURIComponent(buildRecordFile(date, record));
  }

  function autoPlayCheck(checkbox) {
    var player = byId("rpl");
    if (!player || !checkbox) {
      return;
    }
    autoPlayEnabled = !!checkbox.checked;
    if (autoPlayEnabled) {
      player.setAttribute("autoplay", "");
    } else {
      player.removeAttribute("autoplay");
    }
  }

  function onRecordChanged(seekOff) {
    var date = selectedDate();
    var record = selectedRecord();
    var hasSelection = !!(date && record);
    setActionsEnabled(hasSelection);
    // a time picked on the timeline (item 36): applied when the file's metadata is in
    tl.pendingSeek = typeof seekOff === "number" ? seekOff : null;
    tl.want = null;
    tl.cur = hasSelection ? record : "";
    tlDraw();
    if (!hasSelection) {
      return;
    }

    var player = byId("rpl");
    if (!player) {
      return;
    }

    var source = document.createElement("source");
    source.src = buildRecordUrl(date, record);
    // the thumbnail the recorder keeps next to the clip (3.0), shown until the video plays
    player.setAttribute("poster", "/DCIM/" + encodeURIComponent(buildRecordFile(date, record).replace(/[.](mp4|mkv)$/, ".jpg")));
    clearRecordError();
    player.innerHTML = "";
    player.appendChild(source);
    try {
      player.load();
    } catch (e) {
      console.error(e);
    }
  }

  function setDateRecords(records) {
    var recordSelect = byId("recordselect");
    var recordSelectDiv = byId("recordselectdiv");
    if (!recordSelect) {
      return;
    }

    while (recordSelect.firstChild) {
      recordSelect.removeChild(recordSelect.firstChild);
    }

    records.forEach(function (record) {
      var opt = document.createElement("option");
      opt.value = record;
      opt.textContent = record;
      recordSelect.appendChild(opt);
    });

    if (recordSelectDiv) {
      recordSelectDiv.classList.remove("is-loading");
    }

    if (recordSelect.options.length > 0) {
      recordSelect.options[0].selected = true;
      onRecordChanged();
    } else {
      setActionsEnabled(false);
    }
    tl.records = records;
    tlLoad(selectedDate());
  }

  // Item 36, the day's timeline: drawn here (canvas) from viewrecords.cgi?cmd=day_index, one small JSON per day with
  // the start, length and event spans of each file, so the camera only lists files. Click or drag: the player goes to
  // that second (same file: no reload; another file: loaded, then sought). Arrow keys: 10 s (Shift: 1 min).
  var tl = { date: "", seg: 300, spans: [], records: [], v0: 0, v1: 86400, hover: -1, drag: false, cur: "",
             pendingSeek: null, pendingAbs: null, want: null, raf: 0, bound: false };

  function tlColor(name, fallback) {
    var v = "";
    try { v = getComputedStyle(document.documentElement).getPropertyValue(name).trim(); } catch (e) { v = ""; }
    return v || fallback;
  }

  function tlSecOf(t) {
    var m = /^(\d{2})-(\d{2})-(\d{2})/.exec(String(t));
    return m ? parseInt(m[1], 10) * 3600 + parseInt(m[2], 10) * 60 + parseInt(m[3], 10) : -1;
  }

  function tlFmt(sec, short) {
    sec = Math.max(0, Math.floor(sec));
    if (sec >= 86400) return short ? "24:00" : "24:00:00";
    var h = Math.floor(sec / 3600), m = Math.floor(sec / 60) % 60, x = sec % 60;
    var out = ("0" + h).slice(-2) + ":" + ("0" + m).slice(-2);
    return short ? out : out + ":" + ("0" + x).slice(-2);
  }

  // spans: {rec: "HH-MM-SS.mp4", s, end (seconds of the day), ev: [[from, to, unknownTime], ...]}
  function tlSetIndex(idx) {
    var files = idx && Array.isArray(idx.files) ? idx.files : [];
    var seg = idx && idx.seg > 0 ? idx.seg : 300;
    var spans = [];
    files.forEach(function (f) {
      var st = tlSecOf(f.t);
      if (st >= 0) spans.push({ rec: f.t + "." + (f.x === "mkv" ? "mkv" : "mp4"), s: st, d: typeof f.d === "number" ? f.d : -1, e: Array.isArray(f.e) ? f.e : null });
    });
    if (!idx) {		// no index (older CGI, error): the names alone, each file one segment long at most
      tl.records.forEach(function (r) { var st = tlSecOf(r); if (st >= 0) spans.push({ rec: r, s: st, d: -1, e: null }); });
    }
    spans.sort(function (a, b) { return a.s - b.s; });
    spans.forEach(function (sp, i) {
      var next = i + 1 < spans.length ? spans[i + 1].s : Infinity;
      sp.end = sp.d >= 0 ? sp.s + Math.max(1, sp.d) : Math.min(next, sp.s + seg);
      if (sp.end <= sp.s) sp.end = sp.s + 1;
      sp.ev = [];
      if (!sp.e) return;
      if (!sp.e.length) sp.ev.push([sp.s, sp.end, 1]);	// a marker of an older recorder: an event somewhere in the file
      for (var k = 0; k + 1 < sp.e.length; k += 2) {
        var a = sp.s + sp.e[k], b = sp.e[k + 1] < 0 ? sp.end : sp.s + sp.e[k + 1];
        if (a < sp.end) sp.ev.push([a, Math.max(a + 1, Math.min(b, sp.end)), 0]);
      }
    });
    tl.seg = seg; tl.spans = spans;
    tlHint(-1);
    tlDraw();
    if (tl.pendingAbs !== null) { var abs = tl.pendingAbs; tl.pendingAbs = null; tlSeek(abs); }
  }

  function tlLoad(date) {
    tl.date = date;
    if (!date) { tl.spans = []; tlDraw(); return; }
    fetch("cgi-bin/viewrecords.cgi?cmd=day_index&date=" + encodeURIComponent(date), { cache: "no-store" })
      .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(function (idx) { if (date === selectedDate()) tlSetIndex(idx); })
      .catch(function () { if (date === selectedDate()) tlSetIndex(null); });
  }

  function tlSpanAt(sec) {
    for (var i = 0; i < tl.spans.length; i++) if (sec >= tl.spans[i].s && sec < tl.spans[i].end) return tl.spans[i];
    return null;
  }

  function tlPlayhead() {
    var player = byId("rpl");
    for (var i = 0; i < tl.spans.length; i++) {
      if (tl.spans[i].rec === tl.cur) return tl.spans[i].s + (player && isFinite(player.currentTime) ? player.currentTime : 0);
    }
    return -1;
  }

  function tlHint(sec) {
    var hint = byId("timeline24_hint");
    if (!hint) return;
    if (sec < 0) { hint.textContent = tlFmt(tl.v0, true) + " - " + tlFmt(tl.v1, true); return; }
    var sp = tlSpanAt(sec), txt = tlFmt(sec);
    if (!sp) txt += " · " + T("not recorded");
    else {
      txt += " · " + sp.rec;
      if (sp.ev.some(function (e) { return sec >= e[0] && sec < e[1]; })) txt += " · " + T("event");
    }
    hint.textContent = txt;
  }

  function tlDraw() {
    if (tl.raf) return;
    var raf = window.requestAnimationFrame || function (f) { return setTimeout(f, 16); };
    tl.raf = raf(function () { tl.raf = 0; tlPaint(); });
  }

  function tlPaint() {
    var cv = byId("timeline24_canvas");
    if (!cv || !cv.getContext) return;
    var dpr = window.devicePixelRatio || 1, w = cv.clientWidth || 300, h = cv.clientHeight || 44;
    if (cv.width !== Math.round(w * dpr) || cv.height !== Math.round(h * dpr)) {
      cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    }
    var g = cv.getContext("2d");
    g.setTransform(dpr, 0, 0, dpr, 0, 0);
    g.clearRect(0, 0, w, h);
    var v0 = tl.v0, v1 = tl.v1, k = w / (v1 - v0);
    var X = function (sec) { return (sec - v0) * k; };
    var evY = 2, evH = 7, recY = 11, recH = 16, axisY = recY + recH;
    var accent = tlColor("--v2-accent", "#4f46e5"), tally = tlColor("--v2-tally", "#dc3b3b");
    var warn = tlColor("--v2-warn", "#c2780e"), ink = tlColor("--v2-ink", "#1d2129"), muted = tlColor("--v2-muted", "#6b7280");
    g.fillStyle = tlColor("--v2-hover", "#e2e8f0");
    g.fillRect(0, recY, w, recH);
    tl.spans.forEach(function (sp) {
      if (sp.end < v0 || sp.s > v1) return;
      g.globalAlpha = sp.rec === tl.cur ? 1 : 0.55;
      g.fillStyle = accent;
      g.fillRect(X(sp.s), recY, Math.max(1.5, X(sp.end) - X(sp.s)), recH);
      g.globalAlpha = 1;
      sp.ev.forEach(function (e) {
        g.fillStyle = e[2] ? warn : tally;
        g.fillRect(X(e[0]), evY, Math.max(2, X(e[1]) - X(e[0])), evH);
      });
    });
    // the axis: about one label per 70 px
    var steps = [60, 300, 900, 1800, 3600, 7200, 14400], step = 14400, t;
    for (var i = 0; i < steps.length; i++) if ((v1 - v0) / steps[i] <= Math.max(2, w / 70)) { step = steps[i]; break; }
    g.fillStyle = muted;
    g.font = "10px sans-serif";
    g.textBaseline = "top";
    for (t = Math.ceil(v0 / step) * step; t <= v1; t += step) {
      var x = X(t);
      g.fillRect(Math.min(w - 1, Math.round(x)), axisY, 1, 3);
      g.textAlign = x < 16 ? "left" : x > w - 16 ? "right" : "center";
      g.fillText(tlFmt(t, true), x, axisY + 4);
    }
    var ph = tlPlayhead();
    if (ph >= v0 && ph <= v1) { g.fillStyle = ink; g.fillRect(Math.round(X(ph)) - 1, 0, 2, axisY); }
    if (tl.hover >= 0) { g.globalAlpha = 0.45; g.fillStyle = ink; g.fillRect(Math.round(X(tl.hover)), 0, 1, axisY); g.globalAlpha = 1; }
    cv.setAttribute("aria-valuetext", ph >= 0 ? tlFmt(ph) : tlFmt(tl.v0));
  }

  function tlZoom(span, centre) {
    span = Math.max(60, Math.min(86400, span));
    if (!(centre >= 0)) centre = tl.hover >= 0 ? tl.hover : tlPlayhead() >= 0 ? tlPlayhead() : (tl.v0 + tl.v1) / 2;
    tl.v0 = Math.max(0, Math.min(86400 - span, centre - span / 2));
    tl.v1 = tl.v0 + span;
    var z = byId("timeline24_zoom");
    if (z) z.value = String(span);
    tlHint(-1);
    tlDraw();
  }

  function tlApplySeek(player, off) {
    tl.want = { off: off, until: Date.now() + 60000 };
    try { player.currentTime = off; } catch (e) { /* not seekable yet: retried as data arrives */ }
    var p = player.play ? player.play() : null;
    if (p && p.catch) p.catch(function () {});
    tlDraw();
  }

  function tlSeek(sec) {
    var sp = tlSpanAt(sec), off;
    if (!sp) {			// a gap: the next recording, from its start
      for (var i = 0; i < tl.spans.length && !sp; i++) if (tl.spans[i].s > sec) sp = tl.spans[i];
      if (!sp) return;
      off = 0;
    } else off = sec - sp.s;
    var player = byId("rpl");
    if (sp.rec === tl.cur && player && player.readyState >= 1) { tlApplySeek(player, off); return; }
    var sel = byId("recordselect");
    if (!sel) return;
    sel.value = sp.rec;
    if (sel.value !== sp.rec) return;	// no longer in the list
    onRecordChanged(off);
  }

  function tlSecAt(ev) {
    var cv = byId("timeline24_canvas"), r = cv.getBoundingClientRect();
    var x = Math.max(0, Math.min(r.width, ev.clientX - r.left));
    return tl.v0 + x / Math.max(1, r.width) * (tl.v1 - tl.v0);
  }

  function tlBind() {
    var cv = byId("timeline24_canvas"), player = byId("rpl"), zoom = byId("timeline24_zoom");
    if (!cv || tl.bound) return;
    tl.bound = true;
    cv.addEventListener("pointerdown", function (ev) {
      tl.drag = true;
      try { cv.setPointerCapture(ev.pointerId); } catch (e) { /* old browser */ }
      tl.hover = tlSecAt(ev); tlHint(tl.hover); tlDraw();
    });
    cv.addEventListener("pointermove", function (ev) { tl.hover = tlSecAt(ev); tlHint(tl.hover); tlDraw(); });
    cv.addEventListener("pointerup", function (ev) {
      if (!tl.drag) return;
      tl.drag = false;
      tlSeek(tlSecAt(ev));
    });
    cv.addEventListener("pointercancel", function () { tl.drag = false; });
    cv.addEventListener("pointerleave", function () { if (!tl.drag) { tl.hover = -1; tlHint(-1); tlDraw(); } });
    cv.addEventListener("dblclick", function (ev) {
      var z = [86400, 14400, 3600, 900, 300], cur = tl.v1 - tl.v0, i = 0;
      while (i < z.length - 1 && z[i] >= cur) i++;
      tlZoom(z[i], tlSecAt(ev));
    });
    cv.addEventListener("keydown", function (ev) {
      var step = ev.shiftKey ? 60 : 10, ph = tlPlayhead();
      if (ev.key !== "ArrowLeft" && ev.key !== "ArrowRight") return;
      ev.preventDefault();
      tlSeek(Math.max(0, (ph >= 0 ? ph : tl.v0) + (ev.key === "ArrowLeft" ? -step : step)));
    });
    if (zoom) zoom.addEventListener("change", function () { tlZoom(parseInt(zoom.value, 10)); });
    if (window.ResizeObserver) { try { new ResizeObserver(tlDraw).observe(cv); } catch (e) { /* drawn on the next event */ } }
    if (!player) return;
    player.addEventListener("loadedmetadata", function () {
      if (tl.pendingSeek === null) return;
      var off = tl.pendingSeek;
      tl.pendingSeek = null;
      tlApplySeek(player, off);	// picked on the timeline: play from there
    });
    player.addEventListener("timeupdate", tlDraw);
    player.addEventListener("seeked", function () {
      if (tl.want && Math.abs(player.currentTime - tl.want.off) < 2) tl.want = null;
      tlDraw();
    });
    // a fragmented MP4 without an index seeks only into what the browser has: retry while it downloads
    player.addEventListener("progress", function () {
      var w = tl.want, b = player.buffered;
      if (!w || Date.now() > w.until) { tl.want = null; return; }
      if (b && b.length && b.end(b.length - 1) >= w.off && Math.abs(player.currentTime - w.off) >= 2) {
        try { player.currentTime = w.off; } catch (e) { /* next progress */ }
      }
    });
  }

  function onDateChanged() {
    var date = selectedDate();
    var recordSelectDiv = byId("recordselectdiv");
    if (!date) {
      setActionsEnabled(false);
      return;
    }
    loadMotionTimeline(date);

    if (recordSelectDiv) {
      recordSelectDiv.classList.add("is-loading");
    }
    setActionsEnabled(false);

    var cached = recordsMap.get(date);
    if (cached && cached.size > 0) {
      setDateRecords(cached.toArray());
      return;
    }

    fetch("cgi-bin/viewrecords.cgi?cmd=list_records&date=" + encodeURIComponent(date), { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.text();
      })
      .then(function (data) {
        if (date !== selectedDate()) { return; } // another day was picked meanwhile
        var allRecords = safeParseArray(data);
        var recordSet = createSimpleSet();
        allRecords.forEach(function (item) {
          if (item && item.record) {
            recordSet.add(item.record);
          }
        });
        recordsMap.set(date, recordSet);
        setDateRecords(recordSet.toArray());
      })
      .catch(function (e) {
        if (recordSelectDiv) {
          recordSelectDiv.classList.remove("is-loading");
        }
        showRecordError("The list of recordings of this day is unavailable. Retry or inspect the camera logs.");
        console.error(e);
      });
  }

  function downloadRecord() {
    var date = selectedDate();
    var record = selectedRecord();
    if (!(date && record)) {
      return;
    }
    // same-origin link with a file name: downloads without opening a tab (popup blockers)
    var a = document.createElement("a");
    a.href = buildRecordUrl(date, record);
    a.download = buildRecordFile(date, record);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  }

  function showRecordError(msg) {
    var note = byId("videonote");
    var text = byId("videonote_text");
    if (text) text.textContent = msg;
    if (note) note.style.display = "";
  }

  function clearRecordError() {
    var note = byId("videonote");
    var text = byId("videonote_text");
    if (text) text.textContent = "";
    if (note) note.style.display = "none";
  }

  function renderDiskUsage(data) {
    var wrap = byId("disk_usage_wrap");
    var bar = byId("disk_usage_bar");
    var label = byId("disk_usage_label");
    if (!wrap || !bar || !label) { return; }
    var pct = parseInt(data.percent, 10) || 0;
    var availMb = Math.round((data.avail_kb || 0) / 1024);
    var totalMb = Math.round((data.total_kb || 0) / 1024);
    bar.value = pct;
    bar.className = "progress " + (pct >= 90 ? "is-danger" : pct >= 70 ? "is-warning" : "is-info");
    label.textContent = availMb + " MB free of " + totalMb + " MB (" + pct + "% used)";
    wrap.style.display = "";
  }

  function loadDiskUsage() {
    fetch("cgi-bin/viewrecords.cgi?cmd=disk_usage", { cache: "no-store" })
      .then(function (r) { return r.text(); })
      .then(function (t) {
        try { renderDiskUsage(JSON.parse(t)); } catch (e) { /* ignore */ }
      })
      .catch(function () { /* non-critical */ });
  }

  function removeRecord() {
    var date = selectedDate();
    var record = selectedRecord();
    if (!(date && record)) {
      return;
    }

    var file = buildRecordFile(date, record);
    if (!confirm(T("Delete this recording? This cannot be undone.") + "\n" + file)) {
      return;
    }

    clearRecordError();
    var removeBtn = byId("rmbtn");
    if (removeBtn) {
      removeBtn.disabled = true;
    }

    ensureCsrfToken(function () {
      var headers = {};
      if (csrfToken) { headers["X-CSRF-Token"] = csrfToken; }
      fetch("cgi-bin/viewrecords.cgi?cmd=remove_record&record=" + encodeURIComponent(file), {
        method: "POST",
        cache: "no-store",
        headers: headers
      })
      .then(function (r) { return r.text().then(function (t) { return { ok: r.ok, status: r.status, text: t }; }); })
      .then(function (o) {
        var result = {};
        try { result = JSON.parse(o.text); } catch (e) { result = { ok: false, error: o.ok ? "Unexpected response" : "HTTP " + o.status }; }
        if (result.ok !== true) {
          showRecordError("Delete failed: " + (result.error || "unknown error"));
          return;
        }
        var dateSet = recordsMap.get(date);
        if (dateSet) {
          dateSet.delete(record);
        }
        loadDiskUsage();
        if (!dateSet || dateSet.size === 0) {
          recordsMap.delete(date);
          var dateSelect = byId("dateselect");
          if (dateSelect) {
            Array.prototype.slice.call(dateSelect.options).forEach(function (opt) {
              if (opt.value === date) {
                opt.parentNode.removeChild(opt);
              }
            });
          }
          onDateChanged();
        } else {
          setDateRecords(dateSet.toArray());
        }
      })
      .catch(function (e) {
        showRecordError("Delete request failed: " + e);
        console.error(e);
      })
      .finally(function () {
        if (removeBtn) {
          removeBtn.disabled = !(selectedDate() && selectedRecord());
        }
      });
    });
  }

  function populateDates(dates) {
    var dateSelect = byId("dateselect");
    var dateSelectDiv = byId("dateselectdiv");
    if (!dateSelect) {
      return;
    }

    while (dateSelect.firstChild) {
      dateSelect.removeChild(dateSelect.firstChild);
    }

    dates.forEach(function (item) {
      if (!item || !item.date) {
        return;
      }
      var date = item.date;
      recordsMap.set(date, createSimpleSet());
      var opt = document.createElement("option");
      opt.value = date;
      opt.textContent = date;
      dateSelect.appendChild(opt);
    });

    if (dateSelectDiv) {
      dateSelectDiv.classList.remove("is-loading");
    }

    if (dateSelect.options.length > 0) {
      var emptyNote = byId("records_empty");
      if (emptyNote) { emptyNote.parentNode.removeChild(emptyNote); }
      var shownPlayer = byId("rpl");
      if (shownPlayer) { shownPlayer.style.display = ""; }
      dateSelect.disabled = false;
      var recordSelectNow = byId("recordselect");
      if (recordSelectNow) { recordSelectNow.disabled = false; }
      var autoplayNow = byId("autoplay");
      if (autoplayNow) { autoplayNow.disabled = false; }
      dateSelect.selectedIndex = dateSelect.options.length - 1;
      onDateChanged();
      return;
    }

    setActionsEnabled(false);
    var recordSelect = byId("recordselect");
    var autoplay = byId("autoplay");
    if (dateSelect) {
      dateSelect.disabled = true;
    }
    if (recordSelect) {
      recordSelect.disabled = true;
    }
    if (autoplay) {
      autoplay.disabled = true;
    }

    var player = byId("rpl");
    if (player && !byId("records_empty")) {
      var empty = document.createElement("div");
      empty.id = "records_empty";
      empty.className = "notification is-info";
      empty.innerHTML = "No video records found.<br>Enable <strong>'Recording'</strong> service in settings to store video on MicroSD-card.";
      player.style.display = "none";
      player.parentNode.insertBefore(empty, player);
    }
  }

  function initAutoPlayAdvance() {
    var player = byId("rpl");
    if (!player) {
      return;
    }
    player.addEventListener("ended", function () {
      if (!autoPlayEnabled) {
        return;
      }
      var recordSelect = byId("recordselect");
      if (!recordSelect || recordSelect.selectedIndex < 0) {
        return;
      }
      var nextIndex = recordSelect.selectedIndex + 1;
      if (nextIndex < recordSelect.options.length) {
        recordSelect.selectedIndex = nextIndex;
        onRecordChanged();
      }
    });
  }

  var motionTimelineItems = [];
  var motionTimelineDate = "";
  var motionTimelineLoaded = false;
  var MOTION_DOM_LIMIT = 40;

  function buildDatePrefix(epochSec) {
    var d = new Date(epochSec * 1000);
    return "" + d.getFullYear() + "-" + ("0" + (d.getMonth() + 1)).slice(-2) + "-" + ("0" + d.getDate()).slice(-2);
  }

  function formatEventTime(item) {
    if (item.time_utc) return item.time_utc;
    return item.ts ? new Date(item.ts * 1000).toLocaleString() : "";
  }

  function renderMotionTimeline() {
    var list = byId("motion_timeline_list");
    if (!list) return;
    var filter = byId("motion_event_filter");
    var selectedType = filter ? filter.value : "all";
    var items = motionTimelineItems.filter(function (item) {
      return (item.type === "motion_on" || item.type === "motion_off") && (selectedType === "all" || item.type === selectedType);
    }).slice(0, MOTION_DOM_LIMIT);
    while (list.firstChild) list.removeChild(list.firstChild);
    var count = byId("motion_event_count");
    if (count) count.textContent = items.length + (motionTimelineItems.length > items.length ? " shown" : " events");
    if (!items.length) {
      var empty = document.createElement("li"); empty.className = "motion-timeline-empty"; empty.textContent = "No matching events."; list.appendChild(empty); return;
    }
    items.forEach(function (item) {
      var li = document.createElement("li"); li.className = "motion-timeline-item";
      var itemDate = item.ts ? buildDatePrefix(item.ts) : "";
      if (motionTimelineDate && itemDate === motionTimelineDate) li.classList.add("is-selected");
      if (item.snapshot) {
        var img = document.createElement("img"); img.className = "motion-timeline-thumb"; img.alt = "Motion snapshot";
        img.loading = "lazy"; img.decoding = "async"; img.src = item.snapshot; img.onerror = function () { this.style.display = "none"; }; li.appendChild(img);
      }
      var info = document.createElement("div"); info.className = "motion-timeline-info";
      var typeSpan = document.createElement("span"); typeSpan.className = item.type === "motion_on" ? "motion-timeline-type-on" : "motion-timeline-type-off";
      typeSpan.textContent = item.type === "motion_on" ? "Motion started" : "Motion ended"; info.appendChild(typeSpan);
      var timeDiv = document.createElement("div"); timeDiv.className = "motion-timeline-time"; timeDiv.textContent = formatEventTime(item); info.appendChild(timeDiv); li.appendChild(info);
      if (itemDate) li.addEventListener("click", function () {
        var dateSelect = byId("dateselect"); if (!dateSelect) return;
        var at = new Date(item.ts * 1000);
        Array.prototype.slice.call(dateSelect.options).some(function (opt) {
          if (opt.value !== itemDate) return false;
          tl.pendingAbs = at.getHours() * 3600 + at.getMinutes() * 60 + at.getSeconds();	// the timeline seeks there
          dateSelect.value = itemDate; onDateChanged(); return true;
        });
      });
      list.appendChild(li);
    });
  }

  function loadMotionTimeline(activeDate, force) {
    motionTimelineDate = activeDate || motionTimelineDate;
    var panel = byId("motion_timeline_card");
    if (!panel || !panel.open) return;
    if (motionTimelineLoaded && !force) { renderMotionTimeline(); return; }
    var list = byId("motion_timeline_list");
    if (list) list.innerHTML = '<li class="motion-timeline-empty">Loading events...</li>';
    fetch("cgi-bin/motionevents.cgi?limit=80", { cache: "no-store" })
      .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(function (data) { motionTimelineItems = (data.items || []).slice().reverse(); motionTimelineLoaded = true; renderMotionTimeline(); })
      .catch(function () { if (list) list.innerHTML = '<li class="motion-timeline-empty">Events unavailable. Close and reopen to retry.</li>'; motionTimelineLoaded = false; });
  }

  function toggleMotionTimeline() {
    var panel = byId("motion_timeline_card");
    if (panel && panel.open) loadMotionTimeline(motionTimelineDate, false);
  }

  function loadRecordDates() {
    fetch("cgi-bin/viewrecords.cgi?cmd=list_dates", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.text();
      })
      .then(function (data) {
        populateDates(safeParseArray(data));
      })
      .catch(function (e) {
        var ds = byId("dateselectdiv");
        if (ds) { ds.classList.remove("is-loading"); }
        var rs = byId("recordselectdiv");
        if (rs) { rs.classList.remove("is-loading"); }
        showRecordError("Recordings are unavailable. Retry or inspect the camera logs.");
        console.error(e);
      });
  }

  function init() {
    loadDiskUsage();
    var timeline = byId("motion_timeline_card");
    if (timeline) timeline.addEventListener("toggle", toggleMotionTimeline);
    var eventFilter = byId("motion_event_filter");
    if (eventFilter) eventFilter.addEventListener("change", renderMotionTimeline);
    var retry = byId("records_retry");
    if (retry) retry.addEventListener("click", function () { clearRecordError(); recordsMap = createSimpleMap(); loadRecordDates(); });

    var autoplay = byId("autoplay");
    if (autoplay) {
      autoplay.addEventListener("change", function () {
        autoPlayCheck(this);
      });
    }

    initAutoPlayAdvance();
    tlBind();

    loadRecordDates();
  }

  window.downloadRecord = downloadRecord;
  window.removeRecord = removeRecord;
  window.onDateChanged = onDateChanged;
  window.onRecordChanged = onRecordChanged;
  window.autoPlayCheck = autoPlayCheck;
  window.toggleMotionTimeline = toggleMotionTimeline;

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
